(async () => {
  const { readFileSync, existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  if (!inputPath) throw new Error('INPUT_PATH env var missing');
  if (!existsSync(inputPath)) throw new Error(`Input file not found: ${inputPath}`);
  const content = readFileSync(inputPath, 'utf8');
  globalThis.xmlContent = content;
})();

(async () => {
  const jspMod = await import('jsparsers');
  const jsp = jspMod.default || jspMod;
  const xml = jsp.xml();
  // Load XML content into the parser
  if (typeof xml.load === 'function') {
    xml.load(globalThis.xmlContent);
  } else if (typeof xml.parse === 'function') {
    const obj = xml.parse(globalThis.xmlContent);
    globalThis.parsedObj = obj;
  }
  // Convert to TOML
  let tomlStr;
  if (typeof xml.toml === 'function') {
    // Prefer method that works on internal state
    tomlStr = xml.toml();
  } else if (globalThis.parsedObj && typeof xml.toml === 'function') {
    tomlStr = xml.toml(globalThis.parsedObj);
  } else {
    throw new Error('Unable to convert XML to TOML with jsparsers');
  }
  globalThis.tomlString = tomlStr;
})();

(async () => {
  if (typeof globalThis.tomlString !== 'string') throw new Error('Toml result missing');
  console.log(JSON.stringify({ toml: globalThis.tomlString }));
})();
